def maskPII(S: str) -> str:
    if '@' in S:
        S = S.lower()
        name1, rest = S.split('@', 1)
        masked_name1 = name1[0] + '*****' + name1[-1]
        return masked_name1 + '@' + rest
    else:
        digits = [c for c in S if c.isdigit()]
        local = digits[-10:]
        country = digits[:-10]
        local_masked = f"***-***-{local[-4:]}"
        if country:
            country_masked = '+' + '*' * len(country)
            return f"{country_masked}-{local_masked}"
        else:
            return local_masked
